package com.badrulamin.University_Management.service;  import com.badrulamin.University_Management.entity.AdmissionCandidate; import com.badrulamin.University_Management.repository.AdmissionCandidateRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;  import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import java.util.List;  @Service @RequiredArgsConstructor public class AdmissionCandidateService {      private final AdmissionCandidateRepository admissionCandidateRepository;      public Page<AdmissionCandidate> findAll(Pageable pageable) {         return admissionCandidateRepository.findAll(pageable);     }      public AdmissionCandidate findById(Long id) {         return admissionCandidateRepository.findById(id)                 .orElseThrow(() -> new RuntimeException("AdmissionCandidate not found with id: " + id));     }      public AdmissionCandidate save(AdmissionCandidate admissionCandidate) {         return admissionCandidateRepository.save(admissionCandidate);     }      public AdmissionCandidate update(Long id, AdmissionCandidate admissionCandidate) {         findById(id);         admissionCandidate.setId(id);         return admissionCandidateRepository.save(admissionCandidate);     }      public void delete(Long id) {         findById(id);         admissionCandidateRepository.deleteById(id);     }      public long countByStatus(String status) {         return admissionCandidateRepository.countByStatus(status);     } }